contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(amount == 0 || address(this).balance >= amount);
        uint256 blBefore = c.currentBetLimit(); if (__ESBMC_reverted()) return;
        uint256 diffBefore = c.currentDifficulty(); if (__ESBMC_reverted()) return;
        c.OpenToThePublic(); if (__ESBMC_reverted()) return;
        c.OpenToThePublic(); if (__ESBMC_reverted()) return;
        assert(c.currentBetLimit() == blBefore && c.currentDifficulty() == diffBefore);
    }

    receive() external payable {}
}

