// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount == 0 || address(this).balance >= amount);
        uint256 blBefore;
        try c.currentBetLimit() returns (uint256 __r) { blBefore = __r; } catch { return; }
        uint256 diffBefore;
        try c.currentDifficulty() returns (uint256 __r) { diffBefore = __r; } catch { return; }
        try c.OpenToThePublic() {} catch { return; }
        try c.OpenToThePublic() {} catch { return; }
        assertTrue(c.currentBetLimit() == blBefore && c.currentDifficulty() == diffBefore);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
